"""Randomised end-to-end test harness (uses the public auditor)."""
import json, random, subprocess, sys, bisect
from pathlib import Path
sys.path.insert(0, '/workspace'); sys.path.insert(0, '/workspace/submission'); sys.path.insert(0, '/tmp')
from audit import audit
from check import decode
import solver, brute

ENTRY = '/workspace/submission/main.py'
U = 1 << 128


def rand_prefix(rng, clusters):
    if clusters and rng.random() < 0.55:
        base = rng.choice(clusters) + rng.randrange(0, 8)
    else:
        base = rng.randrange(0, 1 << 128) if rng.random() < 0.5 else rng.randrange(0, 1 << 40)
    ln = rng.choice([0, 1, 2, 4, 8, 12, 16, 24, 32, 48, 60, 64, 80, 96, 104,
                     112, 120, 124, 126, 127, 128, 128, 128])
    size = 1 << (128 - ln)
    return base // size * size, ln


def gen_case(rng, idx):
    clusters = [rng.randrange(0, 1 << 128) for _ in range(rng.randint(0, 2))]
    clusters += [rng.randrange(0, 1 << 32) for _ in range(rng.randint(0, 2))]
    ninit = rng.randint(0, 8)
    initial = []
    for _ in range(ninit):
        st, ln = rand_prefix(rng, clusters)
        initial.append([st, ln, rng.randint(0, 12)])
    ntx = rng.randint(0, 3)
    transactions = []
    for _ in range(ntx):
        ops = []
        for _ in range(rng.randint(0, 3)):
            st, ln = rand_prefix(rng, clusters)
            if rng.random() < 0.6:
                ops.append([0, st, ln, rng.randint(0, 12)])
            else:
                ops.append([1, st, ln])
        transactions.append(ops)
    # forwarding versions (to size bursts and check run bounds)
    routes = {}
    for st, ln, hop in initial:
        routes[(st, ln)] = hop
    versions = [solver.compile_atlas([(st, ln, h) for (st, ln), h in routes.items()])]
    for tx in transactions:
        for op, st, ln, hop in tx:
            if op == 0:
                routes[(st, ln)] = hop
            else:
                routes.pop((st, ln), None)
        versions.append(solver.compile_atlas([(st, ln, h) for (st, ln), h in routes.items()]))
    bursts = []
    nbursts = rng.randint(0, 4)
    for _ in range(nbursts):
        v = rng.randrange(len(versions))
        starts = versions[v][0]
        addrs = []
        for _ in range(rng.randint(0, 8)):
            if starts and rng.random() < 0.8:
                r = rng.randrange(len(starts))
                a = starts[r] + (rng.randrange(0, 3) if rng.random() < 0.5 else 0)
                a = min(a, U - 1)
            else:
                a = rng.randrange(0, 1 << 128)
            addrs.append(a)
        bursts.append([v, rng.randint(1, 20), addrs])
    costs = [rng.randint(1, 16), 0, [rng.randint(0, 16) for _ in range(3)]]
    costs[1] = rng.randint(costs[0], min(256, costs[0] + rng.choice([0, 1, 3, 8, 30, 200])))
    return {"initial": initial, "transactions": transactions, "bursts": bursts,
            "cache_pages": rng.randint(0, 12), "costs": costs}, versions


def to_json_case(case):
    def pf(st, ln):
        # printable ipv6 text of a masked prefix
        return text_of(st) + "/" + str(ln)
    initial = [[pf(st, ln), hop] for st, ln, hop in case["initial"]]
    txs = []
    for tx in case["transactions"]:
        out = []
        for op, st, ln, hop in tx:
            if op == 0:
                out.append(["set", pf(st, ln), hop])
            else:
                out.append(["erase", pf(st, ln)])
        txs.append(out)
    bursts = [{"version": v, "repeat": rep,
               "addresses": [text_of(a) for a in addrs]} for v, rep, addrs in case["bursts"]]
    return {"initial": initial, "transactions": txs, "bursts": bursts,
            "cache_pages": case["cache_pages"],
            "costs": {"hit": case["costs"][0], "miss": case["costs"][1],
                      "decode": case["costs"][2]}}


def text_of(x):
    # canonical RFC5952-ish text; python accepts any valid form
    import ipaddress
    return str(ipaddress.IPv6Address(x))


def changes_indep(a, b):
    (sa, ha), (sb, hb) = a, b
    pts = sorted(set(sa) | set(sb))
    rows = []
    for t, p in enumerate(pts):
        end = pts[t + 1] if t + 1 < len(pts) else U
        ia = bisect.bisect_right([x for x in sa if x <= p], p) - 1
        ia = max(i for i in range(len(sa)) if sa[i] <= p)
        ib = max(i for i in range(len(sb)) if sb[i] <= p)
        old, new = ha[ia], hb[ib]
        if old == new:
            continue
        if rows and rows[-1][1] == p and rows[-1][2] == old and rows[-1][3] == new:
            rows[-1][1] = end
        else:
            rows.append([p, end, old, new])
    return [[solver.hexbound(x) for x in r[:2]] + r[2:] for r in rows]


def run(seed, verbose=False):
    rng = random.Random(seed)
    ncases = rng.randint(0, 2)
    cases, allversions = [], []
    for _ in range(ncases):
        c, vs = gen_case(rng, 0)
        cases.append(c); allversions.append(vs)
    total = sum(len(v[0]) for vs in allversions for v in vs)
    if any(len(v[0]) > 64 for vs in allversions for v in vs) or total > 128:
        return None  # out of the tested domain
    request = {"cases": [to_json_case(c) for c in cases]}
    payload = json.dumps(request).encode()
    p = subprocess.run([sys.executable, '-B', ENTRY], input=payload,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if p.returncode != 0:
        raise AssertionError('nonzero exit: %s' % p.stderr[:800])
    actual = decode(p.stdout)
    # independent gold
    gold_cases = []
    payloads = []
    for case, versions in zip(cases, allversions):
        per_version = [[] for _ in versions]
        for v, rep, addrs in case["bursts"]:
            starts = versions[v][0]
            per_version[v].append((rep, [bisect.bisect_right(starts, a) - 1 for a in addrs]))
        obj = brute.brute_case(versions, per_version, tuple(case["costs"]), case["cache_pages"])
        gold_cases.append({"versions": [{"starts": [format(x, "032x") for x in s],
                                         "hops": list(h), "image": ""} for s, h in versions],
                           "changes": [changes_indep(versions[i], versions[i + 1])
                                       for i in range(len(versions) - 1)],
                           "bursts": [[] for _ in case["bursts"]],
                           "objective": obj})
    gold = {"cases": gold_cases}
    audit(request, actual, gold)
    return actual


def main():
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 50
    start = int(sys.argv[2]) if len(sys.argv) > 2 else 0
    bad = 0
    for seed in range(start, start + n):
        try:
            r = run(seed)
        except AssertionError as e:
            print('SEED %d FAILED: %s' % (seed, e)); bad += 1; continue
        except Exception as e:
            print('SEED %d ERROR: %r' % (seed, e)); bad += 1; continue
        if r is None:
            continue
    print('done, %d failures' % bad)


main()
